/**
 * Apps API Endpoints
 * 
 * Handles /apps/:name requests for app metadata
 */

import { Request, Response } from 'express';
import { logger } from '../utils/logger.js';
import { getBaseUrl } from '../utils/urlUtils.js';

// Hardcoded base64 icons - must match info.ts for consistency
const hardcodedIcons: Record<string, string> = {
  'editor': 'data:image/svg+xml;base64,',
  'viewer': 'data:image/svg+xml;base64,',
  'player': 'data:image/svg+xml;base64,',
  'pdf': 'data:image/svg+xml;base64,',
  'camera': 'data:image/svg+xml;base64,',
  'app-center': 'data:image/png;base64,',
  'recorder': 'data:image/svg+xml;base64,',
  'terminal': 'data:image/svg+xml;base64,',
  'system-terminal': 'data:image/svg+xml;base64,',
  'calculator': 'data:image/svg+xml;base64,',
  'file-processor': 'data:image/svg+xml;base64,',
  'ddrm-viewer': 'data:image/svg+xml;base64,',
  'pc2-media-runtime': 'data:image/svg+xml;base64,',
  'dao-dashboard': 'data:image/png;base64,'
};

/**
 * Get app information by name
 * GET /apps/:name
 * Returns app metadata including index_url
 */
export function handleGetApp(req: Request, res: Response): void {
  const appName = req.params.name;
  // Get bosonService from app.locals for public URL resolution via Active Proxy
  const bosonService = req.app?.locals?.bosonService;
  const baseUrl = getBaseUrl(req, bosonService);
  
  logger.info(`[apps.ts] Getting app info for: ${appName}`);
  
  // App map with proper icons
  const appMap: Record<string, any> = {
    'editor': { 
      name: 'editor', 
      title: 'Text Editor', 
      uuid: 'app-editor', 
      uid: 'app-editor', 
      icon: hardcodedIcons['editor'], 
      index_url: `${baseUrl}/apps/editor/index.html` 
    },
    'viewer': { 
      name: 'viewer', 
      title: 'Image Viewer', 
      uuid: 'app-viewer', 
      uid: 'app-viewer', 
      icon: hardcodedIcons['viewer'], 
      index_url: `${baseUrl}/apps/viewer/index.html` 
    },
    'player': { 
      name: 'player', 
      title: 'Media Player', 
      uuid: 'app-player', 
      uid: 'app-player', 
      icon: hardcodedIcons['player'], 
      index_url: `${baseUrl}/apps/player/index.html` 
    },
    'camera': { 
      name: 'camera', 
      title: 'Camera', 
      uuid: 'app-camera', 
      uid: 'app-camera', 
      icon: hardcodedIcons['camera'], 
      index_url: `${baseUrl}/apps/camera/index.html` 
    },
    'app-center': { 
      name: 'app-center', 
      title: 'dApp Centre', 
      uuid: 'app-app-center', 
      uid: 'app-app-center', 
      icon: hardcodedIcons['app-center'], 
      index_url: `${baseUrl}/apps/app-center/index.html`,
      pc2_exclusive: true,
      maximize_on_start: true
    },
    'pdf': { 
      name: 'pdf', 
      title: 'PDF', 
      uuid: 'app-pdf', 
      uid: 'app-pdf', 
      icon: hardcodedIcons['pdf'], 
      index_url: `${baseUrl}/apps/pdf/index.html` 
    },
    'terminal': { 
      name: 'terminal', 
      title: 'Terminal', 
      uuid: 'app-terminal', 
      uid: 'app-terminal', 
      icon: hardcodedIcons['terminal'], 
      index_url: `${baseUrl}/apps/terminal/index.html` 
    },
    'phoenix': { 
      name: 'phoenix', 
      title: 'Phoenix Shell', 
      uuid: 'app-phoenix', 
      uid: 'app-phoenix', 
      icon: hardcodedIcons['terminal'], 
      index_url: `${baseUrl}/apps/phoenix/index.html` 
    },
    'recorder': { 
      name: 'recorder', 
      title: 'Recorder', 
      uuid: 'app-recorder', 
      uid: 'app-recorder', 
      icon: hardcodedIcons['recorder'], 
      index_url: `${baseUrl}/apps/recorder/index.html` 
    },
    'solitaire-frvr': { 
      name: 'solitaire-frvr', 
      title: 'Solitaire FRVR', 
      uuid: 'app-solitaire-frvr', 
      uid: 'app-solitaire-frvr', 
      icon: hardcodedIcons['solitaire-frvr'], 
      index_url: `${baseUrl}/apps/solitaire-frvr/index.html` 
    },
    'calculator': { 
      name: 'calculator', 
      title: 'WASM Calculator', 
      uuid: 'app-calculator', 
      uid: 'app-calculator', 
      icon: hardcodedIcons['calculator'], 
      index_url: `${baseUrl}/apps/calculator/index.html` 
    },
    'file-processor': { 
      name: 'file-processor', 
      title: 'File Analyzer', 
      uuid: 'app-file-processor', 
      uid: 'app-file-processor', 
      icon: hardcodedIcons['file-processor'], 
      index_url: `${baseUrl}/apps/file-processor/index.html` 
    },
    'dao-dashboard': { 
      name: 'dao-dashboard', 
      title: 'Elastos DAO', 
      uuid: 'app-dao-dashboard', 
      uid: 'app-dao-dashboard', 
      icon: hardcodedIcons['dao-dashboard'], 
      index_url: `${baseUrl}/apps/dao-dashboard/index.html`,
      description: 'Elastos DAO governance dashboard - view proposals, council, and vote',
      pc2_exclusive: true,
      maximize_on_start: true
    },
    'ddrm-viewer': { 
      name: 'ddrm-viewer', 
      title: 'Elacity Viewer', 
      uuid: 'app-ddrm-viewer', 
      uid: 'app-ddrm-viewer', 
      icon: hardcodedIcons['ddrm-viewer'], 
      index_url: `${baseUrl}/apps/ddrm-viewer/index.html` 
    },
    'pc2-media-runtime': { 
      name: 'pc2-media-runtime', 
      title: 'Elacity Player', 
      uuid: 'app-pc2-media-runtime', 
      uid: 'app-pc2-media-runtime', 
      icon: hardcodedIcons['pc2-media-runtime'], 
      index_url: `${baseUrl}/apps/pc2-media-runtime/index.html` 
    },
    'system-terminal': { 
      name: 'system-terminal', 
      title: 'System Terminal', 
      uuid: 'app-system-terminal', 
      uid: 'app-system-terminal', 
      icon: hardcodedIcons['system-terminal'], 
      index_url: null, // Built-in window, no external URL
      is_builtin: true,
      pc2_exclusive: true // Only available in PC2 node
    }
  };
  
  // Handle multiple app names separated by |
  const appNames = appName.split('|');
  const results: any[] = [];
  const appInstallService = req.app?.locals?.appInstallService;

  for (const name of appNames) {
    const trimmed = name.trim();
    if (appMap[trimmed]) {
      results.push(appMap[trimmed]);
    } else if (appInstallService) {
      const installed = appInstallService.get(trimmed);
      if (installed) {
        try {
          const manifest = JSON.parse(installed.manifest_json);
          let iconUrl: string | undefined;
          if (manifest.iconDataUrl) {
            iconUrl = manifest.iconDataUrl;
          } else if (installed.icon) {
            iconUrl = `${baseUrl}/installed-apps/${installed.app_name}/${installed.icon}`;
          }
          results.push({
            name: installed.app_name,
            title: installed.title,
            uuid: `app-${installed.app_name}`,
            uid: `app-${installed.app_name}`,
            icon: iconUrl,
            index_url: `${baseUrl}/installed-apps/${installed.app_name}/${manifest.entry || 'index.html'}`,
            installed: true,
          });
        } catch {
          logger.warn(`[apps.ts] Corrupt manifest for installed app: ${trimmed}`);
        }
      }
    }
  }

  if (results.length === 0) {
    logger.warn(`[apps.ts] App not found: ${appName}`);
    res.status(404).json({ error: `App "${appName}" not found` });
    return;
  }
  
  // Return array if multiple apps, single object if one app
  // (window.get_apps expects array, but launch_app.js expects single object when one app)
  if (results.length === 1) {
    res.json([results[0]]); // Always return array for consistency with Puter API
  } else {
    res.json(results);
  }
}

